export function MapPinIcon({
  className = "w-5 h-5",
  color,
}: {
  className?: string;
  color?: string;
}) {
  return (
    <svg
      className={className}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color || "currentColor"}
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M12 21.5c-3.5-4.5-7-8.8-7-12.5a7 7 0 1 1 14 0c0 3.7-3.5 8-7 12.5Z" />
      <circle cx="12" cy="9" r="2.5" />
    </svg>
  );
}

